<section class="py-5 bg-primary text-white"><div class="container py-5"><div class="row align-items-center"><div class="col-lg-7"><h1 class="display-4 fw-bold">Learn skills that move you forward.</h1><p class="lead">Discover practical courses from instructors and learn at your own pace.</p><a href="/courses" class="btn btn-light btn-lg">Explore courses</a></div></div></div></section><section class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h2>Featured courses</h2><p class="text-muted mb-0">Start learning today.</p></div><a href="/courses" class="btn btn-outline-primary">View all</a></div><div class="row g-4"><?php if (!$courses): ?><div class="col-12"><div class="alert alert-info">No published courses are available yet.</div></div><?php endif; ?><?php foreach ($courses as $course): ?><div class="col-md-4"><div class="card h-100 shadow-sm"><div class="card-body"><span class="badge text-bg-light mb-2">Course</span><h3 class="h5"><?= e($course['title']) ?></h3><p class="text-muted small"><?= e(substr((string)$course['description'], 0, 120)) ?></p><div class="d-flex justify-content-between"><span>$<?= e(number_format((float)$course['price'], 2)) ?></span><a href="/course?slug=<?= urlencode($course['slug']) ?>">View course</a></div></div></div></div><?php endforeach; ?></div></section>